		provider.add("book.pastel.guidebook.infused_beverages.page3.text", "Filling and tastes both sweet and savory. What a lovely combination.");
		provider.add("book.pastel.guidebook.infused_beverages.page4.text", "Refreshing, but leaves a bitter taste in my mouth.");
